// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 firstVal, uint256 secondVal) public {
        // Initialize the contract so the SetMinSum guard becomes active.
        c.Initialized();

        // First (fuzzed) setting: identical on both versions.
        vm.prank(address(0xA11CE));
        c.SetMinSum(firstVal);

        // Second (fuzzed) setting after initialization:
        // in the reference C this is reverted by the intitalized guard,
        // in the mutant M it overwrites MinSum.
        vm.prank(address(0xB0B));
        bool ok;
        try c.SetMinSum(secondVal) { ok = true; } catch { ok = false; }

        // General rule: after initialization, SetMinSum never has any effect,
        // so MinSum always equals the pre-initialization value.
        assertTrue(!ok && c.MinSum() == firstVal);
    }
}

