pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 newVal) public {
        vm.assume(newVal != 0);
        // Initialize the contract: after this, SetMinSum must be permanently inert.
        c.Initialized();
        bool ok;
        try c.SetMinSum(newVal) { ok = true; } catch { ok = false; }
        // General rule: after initialization, any SetMinSum call reverts and
        // MinSum remains at its pre-initialization value (0 here).
        assertTrue(!ok && c.MinSum() == 0);
    }
}

