pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, LogFile} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function testFuzz_property(uint256 m1, uint256 m2, uint256 amount) public {
        m1 = bound(m1, 0, type(uint128).max);
        m2 = bound(m2, 0, type(uint128).max);
        amount = bound(amount, m1 + 1, type(uint128).max);

        LogFile log = new LogFile();
        Attacker attacker = new Attacker(c, m2);

        c.SetMinSum(m1);
        c.SetLogFile(address(log));

        vm.deal(address(attacker), amount);
        attacker.deposit(amount);

        vm.warp(block.timestamp + 1);
        c.Initialized();
        vm.warp(block.timestamp + 1);

        attacker.attack(amount);

        // Rule: once initialized, reentrant SetMinSum during Collect must not
        // change MinSum; it stays at the value set before initialization.
        assertTrue(c.MinSum() == m1);
    }
}

contract Attacker {
    C c;
    uint256 m2;

    constructor(C _c, uint256 _m2) {
        c = _c;
        m2 = _m2;
    }

    function deposit(uint256 amt) external payable {
        address(c).call{value: amt}("");
    }

    function attack(uint256 amt) external {
        c.Collect(amt);
    }

    receive() external payable {
        // re-enter SetMinSum while Collect's external call is in flight
        c.SetMinSum(m2);
    }
}

