pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker atk;

    function setUp() public {
        c = new C();
        atk = new Attacker(c);
        c.SetLogFile(address(atk));
    }

    function testFuzz_property(uint256 newVal, uint256 amount, uint256 warpBy) public {
        vm.assume(newVal > 0);
        amount = bound(amount, 1, 1e30);
        warpBy = bound(warpBy, 1, 1e18);

        // attacker deposits so it has balance to collect
        vm.deal(address(atk), amount);
        atk.deposit(amount);
        vm.warp(block.timestamp + warpBy);

        uint256 m0 = c.MinSum();
        atk.collectAndReenter(newVal, amount);

        // Rule: no reentrant SetMinSum during a locked external call may change MinSum.
        assertTrue(c.MinSum() == m0);
    }
}

contract Attacker {
    C c;
    uint256 newVal;
    bool reenter;

    constructor(C _c) { c = _c; }

    function deposit(uint256 amt) external payable {
        c.Put{value: amt}(0);
    }

    function collectAndReenter(uint256 _newVal, uint256 amt) external {
        newVal = _newVal;
        reenter = true;
        c.Collect(amt);
        reenter = false;
    }

    receive() external payable {
        if (reenter) {
            c.SetMinSum(newVal);
        }
    }

    // satisfies LogFile interface so Put's AddMessage does not revert
    function AddMessage(address, uint256, string memory) external pure {}
}

