pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 v1, uint256 v2) public {
        // First call: must succeed and set MinSum to v1 in any version.
        vm.prank(address(1));
        try c.SetMinSum(v1) { assertTrue(c.MinSum() == v1); } catch { assertTrue(false); }

        // Second call with a different value: reference succeeds and updates MinSum.
        vm.assume(v1 != v2);
        bool ok;
        vm.prank(address(2));
        try c.SetMinSum(v2) { ok = true; } catch { ok = false; }

        // General rule: SetMinSum always succeeds (before Initialized) and MinSum
        // always reflects the latest successful call.
        assertTrue(ok && c.MinSum() == v2);
    }
}

