pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address logAddr, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(logAddr != address(0));
        vm.assume(logAddr != address(c));
        vm.assume(uint160(logAddr) > 100);
        amount = bound(amount, 1, 1 ether);

        // Setting the log file must succeed for an uninitialized contract
        vm.prank(actor);
        bool setOk;
        try c.SetLogFile(logAddr) { setOk = true; } catch { setOk = false; }
        assertTrue(setOk);

        // With a valid LogFile configured, a deposit (Put) must succeed:
        // the reference logs via the configured LogFile; the mutant has
        // Log == address(0) and the logging call reverts the whole Put.
        vm.deal(actor, amount);
        vm.prank(actor);
        bool putOk;
        try c.Put{value: amount}(0) { putOk = true; } catch { putOk = false; }

        assertTrue(putOk, "Put must succeed once a LogFile is configured");
    }
}

