pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address logAddr;

    function setUp() public {
        c = new C();
        logAddr = address(new LogFileHelper());
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, 100 ether);

        // Initialize once so the contract accepts the configuration calls.
        c.SetMinSum(0);
        c.SetLogFile(logAddr);
        c.Initialized();

        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}(abi.encodeWithSignature("Put(uint256)", uint256(0)));

        assertTrue(ok && c.Acc(actor).balance == amount, "After SetLogFile succeeds, any Put must succeed and credit the sender's balance");
    }
}

contract LogFileHelper {
    struct Message {
        address Sender;
        string Data;
        uint Val;
        uint Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

