pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, LogFile} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount, uint256 minSum, uint256 lockTime) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 1, 100 ether);
        minSum = bound(minSum, 0, amount);
        lockTime = bound(lockTime, 0, 365 days);

        LogFile lf = new LogFile();
        c.SetMinSum(minSum);
        c.SetLogFile(address(lf));
        c.Initialized();

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(lockTime);

        vm.warp(block.timestamp + lockTime + 1);

        vm.prank(actor);
        bool collected = false;
        try c.Collect(amount) { collected = true; } catch { collected = false; }

        assertTrue(collected && c.Acc(actor).balance == 0, "matured Collect must succeed and clear the balance");
    }
}

